const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={worker:null,ready:false,loaded:false,qcApplied:false,benchmark:null,filled:false,phase3:null,phase4:null,meta:null,primaryFile:null,suppFile:null,primaryInspection:null,suppInspection:null,waterFile:null,waterInspection:null,aoiFile:null,skipped:new Set()};
const status=$('#runtimeStatus'), statusText=$('#runtimeText'), overlay=$('#progressOverlay'), prog=$('#progressBar'), progText=$('#progressText');
function toast(msg,ms=4600){const t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.add('hidden'),ms)}
function busy(v,msg='Working…',pct=8){overlay.classList.toggle('hidden',!v);if(v){prog.style.width=Math.max(2,Math.min(100,pct))+'%';progText.textContent=msg}}
function setRuntime(cls,text){status.className='status '+cls;statusText.textContent=text}
function fmt(n,d=1){if(n===null||n===undefined||Number.isNaN(Number(n)))return '—';return Number(n).toLocaleString(undefined,{maximumFractionDigits:d})}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function downloadText(text,name,mime='text/csv'){const blob=new Blob([text],{type:mime+';charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===id));if(id==='export'&&typeof refreshFigureOptions==='function')refreshFigureOptions();if(typeof updateCoach==='function')updateCoach(id);if(typeof updateWorkspace==='function')updateWorkspace();requestAnimationFrame(()=>$$('.view.active .js-plotly-plot').forEach(g=>window.Plotly?.Plots.resize(g)));window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-btn').forEach(b=>b.onclick=()=>showView(b.dataset.view));

function setupDrop(zoneId,inputId,kind){const zone=$(zoneId),input=$(inputId);zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files[0]){const dt=new DataTransfer();dt.items.add(e.dataTransfer.files[0]);input.files=dt.files;setFile(e.dataTransfer.files[0],kind)}});input.addEventListener('change',()=>{if(input.files[0])setFile(input.files[0],kind)});}
function setFile(file,kind){invalidateWorkspace();state[kind+'File']=file;state[kind+'Inspection']=null;updateCoach();updateWorkspace();const prefix=kind==='primary'?'primary':'supp';$('#'+prefix+'FileName').textContent=file.name;$('#'+prefix+'FileMeta').textContent=`${(file.size/1024/1024).toFixed(2)} MB · ${file.type||'local file'}`;$('#inspectBtn').disabled=!(state.ready&&state.primaryFile);$('#processBtn').disabled=true;}
setupDrop('#primaryDrop','#primaryInput','primary');setupDrop('#suppDrop','#suppInput','supp');

function projectPayload(){return {project_name:$('#projectName').value.trim(),site_name:$('#siteName').value.trim(),timezone:$('#timezone').value,time_basis:$('#timeBasis').value,maximum_qc:Number($('#maxQc').value),timestamp_convention:$('#primaryTimestamp').value,supplemental_timestamp_convention:$('#suppTimestamp').value,latitude:nullableNumber($('#latitude').value),longitude:nullableNumber($('#longitude').value),measurement_height:nullableNumber($('#measurementHeight').value),canopy_height:nullableNumber($('#canopyHeight').value)}}
function nullableNumber(v){return String(v??'').trim()===''?null:Number(v)}

function resetPhase3UI(){state.phase3=null;$$('.p3export').forEach(b=>b.disabled=true);const rep=$('#exportPhase3Report');if(rep)rep.disabled=true;for(const id of ['#p3Ebr','#p3Slope','#p3R2','#p3N','#p3EtTotal','#p3EtEto']){const el=$(id);if(el)el.textContent='—'}const cb=$('#correctionBody');if(cb)cb.innerHTML='<tr><td colspan="5">Run energy & water analysis.</td></tr>';const pw=$('#phase3Warnings');if(pw)pw.innerHTML='<div class="callout">Run energy & water analysis to populate method availability, assumptions and warnings.</div>'}
function initWorker(){
 state.worker=new Worker('/assets/js/py-worker.js?v=20260924workspace',{type:'module'});setRuntime('busy','Loading scientific runtime');
 state.worker.onerror=e=>{runtimeFailure('The analysis runtime could not start. Check your connection and retry.');busy(false);setRuntime('','Runtime error');console.error(e);toast('Scientific runtime worker could not start. Hard-refresh the page and try again.',7000)};
 state.worker.onmessage=e=>{queueMicrotask(()=>{updateCoach();updateWorkspace()});let m=e.data||{};if(typeof m==='string'){try{m=JSON.parse(m)}catch{m={type:'log',message:m}}}
  if(m.type==='ready'){document.getElementById('runtimeNotice').classList.add('hidden');state.ready=true;busy(false);setRuntime('ready','Ready to analyze');$('#inspectBtn').disabled=!state.primaryFile;return}
  if(m.type==='progress'){if(state.ready)busy(true,m.message,m.value||5);setRuntime('busy',m.message);return}
  if(m.type==='error'){if(!state.ready)runtimeFailure(m.message);busy(false);setRuntime('','Runtime error');console.error(m);toast(state.ready?(m.message||'Processing failed.'):'Analysis runtime unavailable. Check the connection notice.',8000);return}
  if(m.type==='inspected'){busy(false);setRuntime('ready','Files inspected');state.primaryInspection=m.primary||null;state.suppInspection=m.supplemental||null;renderInspection();$('#processBtn').disabled=!state.primaryInspection;toast('File structure detected. Verify mappings before processing.');showView('mapping');return}
  if(m.type==='loaded'){clearDerivedResults();if($('#qcChart').data)Plotly.purge($('#qcChart'));$('#exportQcTop').disabled=true;$('#exportQcBottom').disabled=true;$('#qcAuditBody').innerHTML='<tr><td colspan="6">Apply quality control to view the audit.</td></tr>';['#qcRangeRejects','#qcSpikeRejects','#qcVars'].forEach(id=>$(id).textContent='—');busy(false);setRuntime('ready','Project ready');state.loaded=true;state.qcApplied=false;state.meta=m.result;state.benchmark=null;state.filled=false;resetPhase3UI();renderMeta(m.result);renderModules(m.result.capabilities||[]);$('#applyQcBtn').disabled=false;toast('Project standardized. Review quality control before validation.');showView('overview');return}
  if(m.type==='qcDone'){clearDerivedResults();busy(false);setRuntime('ready','QC complete');state.qcApplied=true;state.meta=m.result;state.benchmark=null;state.filled=false;resetPhase3UI();renderMeta(m.result);renderQc(m.result.qc||{});renderModules(m.result.capabilities||[]);toast('Quality control applied. Model validation can now use the screened dataset.');showView('qc');return}
  if(m.type==='capabilities'){busy(false);setRuntime('ready','Readiness updated');if(state.meta)state.meta.capabilities=m.result;renderModules(m.result||[]);toast('Module readiness updated.');return}
  if(m.type==='benchmarkDone'){busy(false);setRuntime('ready','Validation complete');state.benchmark=m.result;renderBenchmark(m.result);toast('Blocked-gap validation complete.');showView('models');return}
  if(m.type==='fillDone'){clearDomainResults();busy(false);setRuntime('ready','Gap filling complete');state.filled=true;resetPhase3UI();renderFilled(m.result);toast('Gap-filled product is ready.');showView('results');return}
  if(m.type==='waterInspected'){busy(false);setRuntime('ready','Water-input file inspected');state.waterInspection=m.water;renderWaterMapping(m.water);$('#loadWaterBtn').disabled=false;toast('Water-input file inspected. Verify the mapping, then add it to the project.');return}
  if(m.type==='waterLoaded'){clearDomainResults();busy(false);setRuntime('ready','Water data added');resetPhase3UI();state.meta=m.result.metadata||state.meta;if(state.meta)renderModules(state.meta.capabilities||[]);toast(`Water input added: ${(m.result.added_variables||[]).join(', ')||'no supported water variable found'}.`);return}
  if(m.type==='phase3Done'){busy(false);setRuntime('ready','Energy & water complete');state.phase3=m.result;renderPhase3(m.result);toast('Energy and water/ET analysis complete.');showView('energywater');return}
  if(m.type==='aoiLoaded'){busy(false);setRuntime('ready','AOI loaded');$('#aoiStatus').innerHTML=`<strong>${fmt(m.result.features,0)} feature(s) loaded.</strong> ${escapeHtml(m.result.name||'GeoJSON')}`;toast('AOI polygons loaded.');return}
  if(m.type==='phase4Done'){busy(false);setRuntime('ready','Carbon & footprint complete');state.phase4=m.result;renderPhase4(m.result);toast('Carbon and footprint analysis complete.');showView('phase4');return}
  if(m.type==='exportReady'){busy(false);setRuntime('ready','Export ready');downloadText(m.text??m.csv??'',m.filename,m.mime||'text/csv');toast('Export created locally.');return}
 };
}
initWorker();

$('#inspectBtn').onclick=()=>{if(!state.primaryFile||!state.ready)return;busy(true,'Inspecting file structure',4);state.worker.postMessage({cmd:'inspect',primaryFile:state.primaryFile,supplementalFile:state.suppFile})};

const UNIT_OPTIONS={
 LE:['','W m-2','kW m-2','MJ m-2 h-1'],H:['','W m-2','kW m-2','MJ m-2 h-1'],NEE:['','umol m-2 s-1','mg CO2 m-2 s-1'],
 sr:['','W m-2','kW m-2','MJ m-2 h-1','MJ m-2 d-1'],rn:['','W m-2','kW m-2','MJ m-2 h-1','MJ m-2 d-1'],g:['','W m-2','kW m-2'],
 at:['','degC','K','degF'],soil_temperature:['','degC','K','degF'],dew_point:['','degC','K','degF'],rh:['','%','fraction'],vpd:['','kPa','hPa','Pa'],vp:['','kPa','hPa','Pa'],pa:['','kPa','hPa','Pa'],
 ws:['','m s-1','mph','km h-1'],ustar:['','m s-1'],sigma_v:['','m s-1'],wind_dir:['','degree','radian'],rain:['','mm interval-1','mm h-1','in interval-1','in h-1'],irrigation:['','mm interval-1','mm h-1','in interval-1','in h-1'],ET:['','mm interval-1','mm h-1','in interval-1'],ETo:['','mm interval-1','mm h-1','in interval-1'],swc:['','m3 m-3','%'],obukhov_length:['','m'],pbl_height:['','m'],wstar:['','m s-1']
};
const GROUP_ORDER=['Time','Fluxes','Radiation / energy','Meteorology','Soil / turbulence'];
function renderInspection(){
 const p=state.primaryInspection,s=state.suppInspection;
 if(!p)return;
 $('#primaryFormatText').textContent=`${p.name} · ${fmt(p.size_bytes/1024/1024,2)} MB${p.row_estimate!==null&&p.row_estimate!==undefined?' · ~'+fmt(p.row_estimate,0)+' rows':''}`;$('#primaryFormatChip').textContent=p.format_label;
 $('#primaryTimestamp').value=p.timestamp_recommendation||'midpoint';$('#primaryTimestamp').disabled=p.format==='eddypro';$('#primaryTimestampNote').textContent=p.timestamp_note||'';
 renderMappingTable('primary',p,$('#primaryMapBody'));renderPreview(p);
 if(s){$('#suppFormatText').textContent=`${s.name} · ${fmt(s.size_bytes/1024/1024,2)} MB${s.row_estimate!==null&&s.row_estimate!==undefined?' · ~'+fmt(s.row_estimate,0)+' rows':''}`;$('#suppFormatChip').textContent=s.format_label;$('#suppTimestamp').value=s.timestamp_recommendation||'midpoint';$('#suppTimestamp').disabled=s.format==='cimis';$('#suppTimestampNote').textContent=s.timestamp_note||'';renderMappingTable('supp',s,$('#suppMapBody'));}
 else{$('#suppFormatText').textContent='No supplemental file selected';$('#suppFormatChip').textContent='OPTIONAL';$('#suppMapBody').innerHTML='<tr><td colspan="4">No supplemental file selected. The primary dataset can be processed alone.</td></tr>';$('#suppTimestampNote').textContent='';}
 const mapped=Object.values(p.mapping||{}).filter(x=>x.column).length;const targets=['LE','H','NEE'].filter(k=>p.mapping?.[k]?.column);
 $('#mappingSummary').innerHTML=`<div class="source-badge-row"><div class="source-badge"><b>${escapeHtml(p.format_label)}</b> detected</div><div class="source-badge"><b>${mapped}</b> mapped roles</div><div class="source-badge"><b>${targets.length?targets.join(', '):'No flux target auto-detected'}</b></div>${s?`<div class="source-badge">Supplemental: <b>${escapeHtml(s.format_label)}</b></div>`:''}</div>`;
}
function renderMappingTable(prefix,inspection,tbody){const specialized=(inspection.format==='eddypro')||(prefix==='supp'&&inspection.format==='cimis');let html='';const groups=inspection.role_groups||{};for(const g of GROUP_ORDER){const roles=groups[g]||[];html+=`<tr class="group-row"><td colspan="4">${escapeHtml(g)}</td></tr>`;for(const role of roles){const info=inspection.mapping?.[role]||{},conf=Number(info.confidence||0),cls=conf>=.85?'high':conf>=.55?'medium':'';const sourceOpts=['<option value="">— not mapped —</option>',...(inspection.columns||[]).map(c=>`<option value="${escapeHtml(c)}" ${c===info.column?'selected':''}>${escapeHtml(c)}</option>`)].join('');const unitOpts=unitSelectOptions(role,info.unit);const disabled=specialized?'disabled':'';html+=`<tr data-role="${escapeHtml(role)}"><td class="role-label">${escapeHtml(info.label||role)}${info.canonical_unit?`<small>→ ${escapeHtml(info.canonical_unit)}</small>`:''}</td><td><select class="map-col" data-prefix="${prefix}" data-role="${role}" ${disabled}>${sourceOpts}</select></td><td>${unitOpts?`<select class="map-unit" data-prefix="${prefix}" data-role="${role}" ${disabled}>${unitOpts}</select>`:'<span class="muted">—</span>'}</td><td><span class="confidence ${cls}"><i></i>${conf?Math.round(conf*100)+'%':'manual'}</span></td></tr>`;}}
 tbody.innerHTML=html;if(specialized){const note=document.createElement('tr');note.innerHTML=`<td colspan="4" class="mapping-ok">Specialized ${escapeHtml(inspection.format_label)} parser is active; detected mappings are shown for audit and do not need editing.</td>`;tbody.appendChild(note)} }
function unitSelectOptions(role,detected){if(['timestamp','date','time','qc_LE','qc_H','qc_NEE'].includes(role))return '';const opts=[...(UNIT_OPTIONS[role]||[''])];if(detected&&!opts.includes(detected))opts.splice(1,0,detected);return opts.map(u=>`<option value="${escapeHtml(u)}" ${u===detected?'selected':''}>${escapeHtml(u||'assume canonical')}</option>`).join('')}
function renderPreview(p){const rows=p.preview||[];if(!rows.length){$('#previewHead').innerHTML='';$('#previewBody').innerHTML='<tr><td>No preview rows available.</td></tr>';return}const cols=(p.columns||[]).slice(0,18);$('#previewHead').innerHTML='<tr>'+cols.map(c=>`<th>${escapeHtml(c)}</th>`).join('')+'</tr>';$('#previewBody').innerHTML=rows.map(r=>'<tr>'+cols.map(c=>`<td title="${escapeHtml(r[c]??'')}">${escapeHtml(r[c]??'')}</td>`).join('')+'</tr>').join('')}
function buildSpec(prefix,inspection){const spec=JSON.parse(JSON.stringify(inspection));spec.mapping=spec.mapping||{};$$(`.map-col[data-prefix="${prefix}"]`).forEach(el=>{const role=el.dataset.role;spec.mapping[role]=spec.mapping[role]||{};spec.mapping[role].column=el.value||null});$$(`.map-unit[data-prefix="${prefix}"]`).forEach(el=>{const role=el.dataset.role;spec.mapping[role]=spec.mapping[role]||{};spec.mapping[role].unit=el.value||''});spec.timestamp_recommendation=prefix==='primary'?$('#primaryTimestamp').value:$('#suppTimestamp').value;return spec}

$('#processBtn').onclick=()=>{if(!state.primaryInspection||!state.primaryFile)return;const primarySpec=buildSpec('primary',state.primaryInspection);const suppSpec=state.suppInspection?buildSpec('supp',state.suppInspection):null;const project=projectPayload();project.timestamp_convention=$('#primaryTimestamp').value;project.supplemental_timestamp_convention=$('#suppTimestamp').value;busy(true,'Standardizing mapped project',3);state.worker.postMessage({cmd:'loadUniversal',primaryFile:state.primaryFile,supplementalFile:state.suppFile,primarySpec,supplementalSpec:suppSpec,project})};

function gapValue(g,key,suffix=''){if(!g||g.available===false||g[key]===undefined)return '—';return fmt(g[key],key.includes('gap')?2:1)+suffix}
function renderMeta(m){
 $('#mRecords').textContent=fmt(m.records,0);$('#mPeriod').textContent=(m.start||'').slice(0,10)+' → '+(m.end||'').slice(0,10);$('#mStep').textContent=fmt(m.timestep_minutes,0)+' min';const ext=m.external?.station||m.external?.type||'None';$('#mStation').textContent=ext;
 $('#mLeMissing').textContent=gapValue(m.LE,'missing_pct','%');$('#mHMissing').textContent=gapValue(m.H,'missing_pct','%');$('#mLeGap').textContent=gapValue(m.LE,'longest_gap_days',' d');$('#mHGap').textContent=gapValue(m.H,'longest_gap_days',' d');
 $('#datasetProject').textContent=m.project?.project_name||m.project?.site_name||'Untitled project';$('#datasetSource').textContent=m.source?.type||m.source?.format||'—';$('#datasetPeriod').textContent=$('#mPeriod').textContent;$('#datasetRows').textContent=fmt(m.records,0);$('#datasetStep').textContent=$('#mStep').textContent;$('#datasetStation').textContent=ext;
 renderPredictors(m.predictors||[]);plotRaw(m.plot||{});$('#exportRawBtn').disabled=false;$('#refreshCapabilities').disabled=false;$('#applyQcBtn').disabled=false;
 const availableTargets=['LE','H','NEE'].filter(t=>m[t]?.available&&Number(m[t]?.observed||0)>20);$$('.targetCheck,.fillTarget').forEach(el=>{el.disabled=!availableTargets.includes(el.value);if(el.disabled)el.checked=false});$('#benchmarkBtn').disabled=!availableTargets.length;$('#fillBtn').disabled=!availableTargets.length;
}
function renderPredictors(rows){const tb=$('#predictorBody');tb.innerHTML=rows.map(r=>`<tr><td>${escapeHtml(r.variable)}</td><td>${fmt(r.available_pct)}%</td><td>${fmt(r.n,0)}</td><td><div class="bar" style="width:150px"><i style="width:${Math.min(100,r.available_pct)}%"></i></div></td></tr>`).join('')||'<tr><td colspan="4">No mapped predictors detected.</td></tr>'}
function plotRaw(p){if(!window.Plotly)return;const x=p.datetime||[],tr=[];if(p.LE)tr.push({x,y:p.LE,name:'LE measured',mode:'lines',line:{width:1.3}});if(p.H)tr.push({x,y:p.H,name:'H measured',mode:'lines',line:{width:1.1}});if(p.NEE)tr.push({x,y:p.NEE,name:'NEE / CO₂ flux',mode:'lines',line:{width:1.0},yaxis:'y2'});const lay=darkLayout('Mapped flux time series','W m⁻²');if(p.NEE){lay.yaxis2={title:'NEE',overlaying:'y',side:'right',gridcolor:'transparent'};lay.margin.r=62}Plotly.newPlot('rawChart',tr,lay,{responsive:true,displaylogo:false})}
function darkLayout(title,ytitle=''){const t=plotTheme();return {title:{text:title,font:{size:13,color:t.ink},x:.02,xanchor:'left'},paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{color:t.text,size:10.5,family:'Inter, Segoe UI, Arial, sans-serif'},margin:{l:58,r:22,t:52,b:48},legend:{orientation:'h',y:1.13,font:{size:9.5,color:t.text}},xaxis:{gridcolor:t.grid,zerolinecolor:t.zero,linecolor:t.axis,tickcolor:t.axis,automargin:true},yaxis:{title:ytitle,gridcolor:t.grid,zerolinecolor:t.zero,linecolor:t.axis,tickcolor:t.axis,automargin:true}}}


function qcConfig(){return {spike_enabled:$('#spikeEnabled').checked,spike_window_hours:Number($('#spikeWindow').value),spike_sigma:Number($('#spikeSigma').value),ranges:{LE:[Number($('#leMin').value),Number($('#leMax').value)],H:[Number($('#hMin').value),Number($('#hMax').value)],NEE:[Number($('#neeMin').value),Number($('#neeMax').value)]}}}
$('#applyQcBtn').onclick=()=>{if(!state.loaded)return;busy(true,'Applying quality control',5);state.worker.postMessage({cmd:'qc',config:qcConfig()})};
function renderQc(q){const a=q.audit||[],z=q.summary||{};$('#qcRangeRejects').textContent=fmt(z.range_rejections,0);$('#qcSpikeRejects').textContent=fmt(z.spike_rejections,0);$('#qcVars').textContent=fmt(z.variables_screened,0);$('#qcAuditBody').innerHTML=a.map(r=>`<tr><td>${escapeHtml(r.variable)}</td><td>${fmt(r.n_before,0)}</td><td>${fmt(r.n_range_rejected,0)}</td><td>${fmt(r.n_spike_rejected,0)}</td><td>${fmt(r.n_after,0)}</td><td>${fmt(r.missing_pct_after,1)}%</td></tr>`).join('')||'<tr><td colspan="6">No QC audit rows.</td></tr>';$('#exportQcTop').disabled=false;$('#exportQcBottom').disabled=false;plotQc(q.plot||{})}
function plotQc(p){if(!window.Plotly)return;const x=p.datetime||[],tr=[];for(const t of ['LE','H','NEE']){const pre=p[t+'_pre_phase2_qc'],post=p[t];if(pre)tr.push({x,y:pre,name:`${t} before`,mode:'markers',marker:{size:2},opacity:.25});if(post)tr.push({x,y:post,name:`${t} accepted`,mode:'lines',line:{width:1}})}if(tr.length)Plotly.newPlot('qcChart',tr,darkLayout('Before and after quality control','Flux'),{responsive:true,displaylogo:false})}

function renderModules(rows){const wrap=$('#moduleCards');if(!rows.length){wrap.innerHTML='<div class="callout">No module readiness information is available.</div>';return}wrap.innerHTML=rows.map(r=>{const skipped=state.skipped.has(r.id),statusName=skipped?'skipped':r.status,statusText=skipped?'Skipped':r.status==='ready'?'Ready':'Needs data';const req=(r.missing_required||[]),rec=(r.missing_recommended||[]);return `<div class="module-card ${statusName}" data-module="${escapeHtml(r.id)}"><div class="module-top"><h3>${escapeHtml(r.label)}</h3><span class="module-status ${statusName}">${statusText}</span></div><p>${escapeHtml(r.help)}</p><div class="requirement-list">${req.length?`<div class="requirement-row"><strong>Required:</strong> ${escapeHtml(req.join(', '))}</div>`:'<div class="requirement-row"><strong>Required inputs:</strong> available</div>'}${rec.length?`<div class="requirement-row"><strong>Recommended:</strong> ${escapeHtml(rec.join(', '))}</div>`:'<div class="requirement-row"><strong>Recommended:</strong> available / not needed</div>'}</div><div class="module-actions">${skipped?`<button class="btn btn-secondary module-unskip" data-id="${r.id}">Restore</button>`:r.status==='ready'?`<button class="btn btn-primary module-use" data-id="${r.id}">Use detected data</button><button class="btn btn-ghost module-skip" data-id="${r.id}">Skip</button>`:`<button class="btn btn-secondary module-add" data-id="${r.id}" data-missing="${escapeHtml(req.join(', '))}">Add data</button><button class="btn btn-ghost module-skip" data-id="${r.id}">Skip</button>`}</div></div>`}).join('');
 $$('.module-skip',wrap).forEach(b=>b.onclick=()=>{state.skipped.add(b.dataset.id);renderModules(rows)});$$('.module-unskip',wrap).forEach(b=>b.onclick=()=>{state.skipped.delete(b.dataset.id);renderModules(rows)});$$('.module-add',wrap).forEach(b=>b.onclick=()=>{toast(`Missing for this module: ${b.dataset.missing||'additional input'}. Add the data or site information, then refresh readiness.`,7000);showView('setup')});$$('.module-use',wrap).forEach(b=>b.onclick=()=>{if(b.dataset.id==='gap_filling'){showView('models');toast('Gap-filling inputs are ready.')}else if(['energy_balance','et_analysis','irrigation'].includes(b.dataset.id)){showView('energywater');toast('Energy and water inputs are ready. Configure the options and run the analysis.')}else if(['ustar','carbon','footprint'].includes(b.dataset.id)){showView('phase4');toast('Carbon/footprint inputs are ready.')}else{toast('Inputs are ready for this optional module.',6500)}});
}
function sendProjectUpdate(){if(!state.loaded)return;busy(true,'Updating module readiness',20);state.worker.postMessage({cmd:'updateProject',project:projectPayload()})}
$('#saveSiteInfo').onclick=sendProjectUpdate;$('#refreshCapabilities').onclick=sendProjectUpdate;

$('#benchmarkBtn').onclick=()=>{if(!state.loaded)return;const targets=$$('.targetCheck:checked:not(:disabled)').map(x=>x.value),candidates=$$('.candidateCheck:checked').map(x=>x.value),durations=$$('.durationCheck:checked').map(x=>Number(x.value));if(!targets.length||!candidates.length||!durations.length)return toast('Choose at least one available target, method and gap duration.');busy(true,'Starting blocked validation',2);state.worker.postMessage({cmd:'benchmark',targets,candidates,durations,windows:Number($('#validationWindows').value)})};
function renderBenchmark(r){
 const sum=r.summary||[],best=r.best||[],bestKeys=new Set(best.map(x=>`${x.target}|${x.gap_days}|${x.model}`));
 $('#benchBody').innerHTML=sum.sort((a,b)=>a.target.localeCompare(b.target)||a.gap_days-b.gap_days||Number(a.rmse)-Number(b.rmse)).map(x=>{const isBest=bestKeys.has(`${x.target}|${x.gap_days}|${x.model}`);return `<tr class="${isBest?'best':''}"><td>${x.target}</td><td>${fmt(x.gap_days)} d</td><td>${escapeHtml(x.model)} ${isBest?'<span class="pill best">SELECTED</span>':''}</td><td>${fmt(x.n,0)}</td><td>${fmt(x.rmse,2)}</td><td>${fmt(x.mae,2)}</td><td>${fmt(x.bias,2)}</td><td>${fmt(x.r2,3)}</td><td>${fmt(x.windows,0)}</td></tr>`}).join('')||'<tr><td colspan="9">No successful validation rows.</td></tr>';
 $('#bestRules').innerHTML=best.map(x=>`<div class="source-card"><h4>${x.target} · ${fmt(x.gap_days)} d</h4><div class="kv"><span>Selected</span><b>${escapeHtml(x.model)}</b></div><div class="kv"><span>RMSE</span><b>${fmt(x.rmse,2)}</b></div><div class="kv"><span>Bias</span><b>${fmt(x.bias,2)}</b></div><div class="kv"><span>R²</span><b>${fmt(x.r2,3)}</b></div></div>`).join('')||'<div class="callout">No successful model selection.</div>';
 const seg=(r.segments||[]).filter(x=>x.segment_type==='daynight').sort((a,b)=>a.target.localeCompare(b.target)||a.gap_days-b.gap_days||a.model.localeCompare(b.model));
 $('#segmentBody').innerHTML=seg.slice(0,120).map(x=>`<tr><td>${x.target}</td><td>${fmt(x.gap_days)} d</td><td>${escapeHtml(x.model)}</td><td>${escapeHtml(x.segment)}</td><td>${fmt(x.n,0)}</td><td>${fmt(x.rmse,2)}</td><td>${fmt(x.bias,2)}</td></tr>`).join('')||'<tr><td colspan="7">No day/night diagnostics available.</td></tr>';
 const seas=(r.segments||[]).filter(x=>x.segment_type==='season').sort((a,b)=>a.target.localeCompare(b.target)||a.gap_days-b.gap_days||a.model.localeCompare(b.model)||a.segment.localeCompare(b.segment));
 $('#seasonBody').innerHTML=seas.slice(0,160).map(x=>`<tr><td>${x.target}</td><td>${fmt(x.gap_days)} d</td><td>${escapeHtml(x.model)}</td><td>${escapeHtml(x.segment)}</td><td>${fmt(x.n,0)}</td><td>${fmt(x.rmse,2)}</td><td>${fmt(x.mae,2)}</td><td>${fmt(x.bias,2)}</td><td>${fmt(x.r2,3)}</td></tr>`).join('')||'<tr><td colspan="9">No seasonal diagnostics available.</td></tr>';
 $('#dayNightBasis').textContent=`Day/night definition: ${r.daynight_basis||'not available'}`;
 plotBenchmark(sum);$('#adaptiveOption').disabled=false;$('#adaptiveOption').checked=true;$$('[data-export-benchmark]').forEach(b=>b.disabled=false);$('#exportSummary').disabled=false;$('#exportSegments').disabled=false;$('#exportCalibration').disabled=false;$('#exportReport').disabled=false;
}
function plotBenchmark(rows){if(!window.Plotly||!rows.length)return;const traces=[],combos=[...new Set(rows.map(r=>r.target+'|'+r.model))];for(const c of combos){const [target,model]=c.split('|'),sub=rows.filter(r=>r.target===target&&r.model===model).sort((a,b)=>a.gap_days-b.gap_days);traces.push({x:sub.map(r=>r.gap_days),y:sub.map(r=>r.rmse),name:`${target} · ${model}`,mode:'lines+markers'})}const lay=darkLayout('Blocked-gap validation RMSE','RMSE');lay.xaxis.title='Artificial gap duration (days)';Plotly.newPlot('benchmarkChart',traces,lay,{responsive:true,displaylogo:false})}

$('#fillBtn').onclick=()=>{if(!state.loaded)return;const targets=$$('.fillTarget:checked:not(:disabled)').map(x=>x.value);if(!targets.length)return toast('No available LE/H target is selected.');const adaptive=$('#adaptiveOption').checked&&state.benchmark,mode=adaptive?'adaptive':'fixed',fixed=$('#fixedModel').value;busy(true,'Building final gap-filled product',3);state.worker.postMessage({cmd:'fill',targets,mode,fixedModel:fixed,maxGapDays:Number($('#maxGapDays').value)})};
function renderFilled(r){const cards=[];for(const [target,counts] of Object.entries(r.source_counts||{})){const items=Object.entries(counts).map(([k,v])=>`<div class="kv"><span>${escapeHtml(k)}</span><b>${fmt(v,0)}</b></div>`).join('');const gc=r.gap_class_counts?.[target]||{},classes=Object.entries(gc).map(([k,v])=>`<div class="kv"><span>${escapeHtml(k)}</span><b>${fmt(v,0)}</b></div>`).join('');cards.push(`<div class="source-card"><h4>${target} provenance</h4>${items}${classes?`<div class="spacer10"></div><h4>Filled gap classes</h4>${classes}`:''}</div>`)}$('#sourceCounts').innerHTML=cards.join('')||'<div class="muted">No filled targets.</div>';plotFilled(r.plot||{});plotET(r.daily_et||[]);$('#intervalNote').innerHTML=`<strong>Intervals:</strong> ${escapeHtml(r.interval_note||'Empirical intervals are available only after blocked validation.')}`;$('#exportCompact').disabled=false;$('#exportFull').disabled=false}
function plotFilled(p){
 if(!window.Plotly)return;
 const x=p.datetime||[],tr=[];
 for(const [target,color] of [['LE','#087d76'],['H','#b56424'],['NEE','#7863a6']]){
  const final=p[target+'_filled'],measured=p[target+'_original'],lower=p[target+'_empirical_lower95'],upper=p[target+'_empirical_upper95'];
  if(lower&&upper){
   let start=null,shown=false;
   const addBand=end=>{if(start===null)return;const xs=x.slice(start,end),lo=lower.slice(start,end),hi=upper.slice(start,end),group=target+'_interval';
    tr.push({x:xs,y:lo,name:target+' interval',legendgroup:group,mode:'lines',line:{width:0,color},showlegend:false,hoverinfo:'skip'});
    tr.push({x:xs,y:hi,name:target+' empirical 95% interval',legendgroup:group,mode:'lines',line:{width:0,color},fill:'tonexty',fillcolor:color+'25',showlegend:!shown,hoverinfo:'skip'});shown=true;start=null;};
   for(let i=0;i<=x.length;i++){const valid=i<x.length&&lower[i]!=null&&upper[i]!=null&&Number.isFinite(lower[i])&&Number.isFinite(upper[i]);if(valid){if(start===null)start=i}else addBand(i)}
  }
  if(final)tr.push({x,y:final,name:target+' reconstructed series',mode:'lines',connectgaps:false,line:{width:1.6,color}});
  if(measured)tr.push({x,y:measured,name:target+' measured',mode:'lines',connectgaps:false,line:{width:1,color:'#526c83',dash:'dot'}});
 }
 const layout=darkLayout('Measured and reconstructed fluxes','H, LE (W m⁻²)');if(p.NEE_filled||p.NEE_original){tr.filter(t=>t.name.startsWith('NEE')).forEach(t=>t.yaxis='y2');layout.yaxis2={title:'NEE (µmol m⁻² s⁻¹)',overlaying:'y',side:'right',showgrid:false};layout.margin.r=65}Plotly.newPlot('filledChart',tr,layout,{responsive:true,displaylogo:false});
}
function plotET(rows){if(!window.Plotly||!rows.length)return;Plotly.newPlot('etChart',[{x:rows.map(r=>r.date),y:rows.map(r=>r.ET_mm_day),type:'bar',name:'ET'}],darkLayout('Daily ET derived from final LE','mm d⁻¹'),{responsive:true,displaylogo:false})}



