function renderWaterMapping(w){if(!w)return;$('#waterFormatChip').textContent=w.format_label||w.format||'Mapped';$('#waterTimestamp').value=w.timestamp_recommendation||'end';const roles=['timestamp','date','time','irrigation','rain','ETo','swc'];let rows='';for(const role of roles){const info=w.mapping?.[role]||{},opts=['<option value="">— not mapped —</option>',...(w.columns||[]).map(c=>`<option value="${escapeHtml(c)}" ${c===info.column?'selected':''}>${escapeHtml(c)}</option>`)].join(''),unit=unitSelectOptions(role,info.unit);rows+=`<tr><td>${escapeHtml(info.label||role)}</td><td><select class="water-map-col" data-role="${role}">${opts}</select></td><td>${unit?`<select class="water-map-unit" data-role="${role}">${unit}</select>`:'—'}</td></tr>`}$('#waterMappingArea').innerHTML=`<div><strong>${escapeHtml(w.format_label||w.format)}</strong> · ${fmt(w.size_bytes/1024/1024,2)} MB</div><div class="spacer10"></div><div class="mapping-table-wrap"><table class="table"><thead><tr><th>Role</th><th>Source column</th><th>Unit</th></tr></thead><tbody>${rows}</tbody></table></div><div class="field-note">Map either Timestamp, Date + Time, or a Date-only column for daily irrigation/applied-water totals.</div>`}
function buildWaterSpec(){const spec=JSON.parse(JSON.stringify(state.waterInspection||{}));spec.mapping=spec.mapping||{};$$('.water-map-col').forEach(el=>{const role=el.dataset.role;spec.mapping[role]=spec.mapping[role]||{};spec.mapping[role].column=el.value||null});$$('.water-map-unit').forEach(el=>{const role=el.dataset.role;spec.mapping[role]=spec.mapping[role]||{};spec.mapping[role].unit=el.value||''});return spec}
$('#loadWaterBtn').onclick=()=>{if(!state.waterFile||!state.waterInspection)return;busy(true,'Aligning optional water inputs',8);state.worker.postMessage({cmd:'loadWater',waterFile:state.waterFile,waterSpec:buildWaterSpec(),timestampConvention:$('#waterTimestamp').value})};

function renderPhase3(r){const s=r.summary||{},e=s.energy||{},m=e.measured_primary||{},daily=r.water_daily||[];$('#p3Ebr').textContent=fmt(m.ratio_of_sums,3);$('#p3Slope').textContent=fmt(m.slope,3);$('#p3R2').textContent=fmt(m.r2,3);$('#p3N').textContent=fmt(m.n,0);const accepted=daily.filter(x=>x.complete_enough&&x.ET_phase3_mm_day!==null&&x.ET_phase3_mm_day!==undefined),etTotal=accepted.reduce((a,x)=>a+Number(x.ET_phase3_mm_day||0),0),ratios=daily.map(x=>Number(x.ET_over_ETo)).filter(Number.isFinite);$('#p3EtTotal').textContent=accepted.length?fmt(etTotal,1)+' mm':'—';$('#p3EtEto').textContent=ratios.length?fmt(ratios.reduce((a,b)=>a+b,0)/ratios.length,2):'—';
 $('#correctionBody').innerHTML=(r.corrections||[]).map(c=>`<tr><td>${escapeHtml(c.method)}</td><td><span class="pill ${c.status==='ready'?'best':''}">${escapeHtml(c.status||'—')}</span></td><td>${fmt(c.n_applied,0)}</td><td>${fmt(c.closure?.ratio_of_sums,3)}</td><td>${escapeHtml(c.reason||c.note||(c.low_height_warning?'Low-height applicability warning':'Ready'))}</td></tr>`).join('')||'<tr><td colspan="5">No correction diagnostics available.</td></tr>';
 const warns=s.warnings||[];const wm=s.water||{};$('#phase3Warnings').innerHTML=`<div class="source-grid"><div class="source-card"><h4>Energy inputs</h4><div class="kv"><span>Rn</span><b>${escapeHtml(e.rn_source||'missing')}</b></div><div class="kv"><span>G mode</span><b>${escapeHtml(e.g?.mode||e.g?.status||'missing')}</b></div><div class="kv"><span>Daylight</span><b>${escapeHtml(e.daylight_source||'—')}</b></div></div><div class="source-card"><h4>Water inputs</h4><div class="kv"><span>ETo</span><b>${escapeHtml(wm.ETo_source||'not supplied')}</b></div><div class="kv"><span>Rain</span><b>${escapeHtml(wm.rain_source||'not supplied')}</b></div><div class="kv"><span>Irrigation</span><b>${escapeHtml(wm.irrigation_source||'not supplied')}</b></div><div class="kv"><span>SWC</span><b>${escapeHtml(wm.SWC_source||'not supplied')}</b></div></div></div>${warns.length?`<div class="spacer10"></div><div class="callout warnbox"><strong>Method notes / warnings</strong><ul>${warns.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></div>`:'<div class="spacer10"></div><div class="callout"><strong>No additional energy/water warnings.</strong></div>'}`;
 plotEnergyP3(r.plot_energy||[],m,e.minimum_available_energy_wm2||20);plotMonthlyEbr(r.energy_monthly||[]);plotDailyEtP3(daily);plotCumulativeWater(daily);plotWaterSwc(daily);$$('.p3export').forEach(b=>b.disabled=false);$('#exportPhase3Report').disabled=false}
function plotEnergyP3(rows,m,minAe=20){if(!window.Plotly||!rows.length)return;const x=[],y=[];for(const r of rows){const ae=Number(r.rn_phase3)-Number(r.g_phase3_surface),te=Number(r.H_phase3_measured)+Number(r.LE_phase3_measured);if(Number.isFinite(ae)&&Number.isFinite(te)&&ae>Number(minAe)&&Boolean(r.phase3_daylight)){x.push(ae);y.push(te)}}const max=Math.max(1,...x,...y),tr=[{x,y,type:'scattergl',mode:'markers',name:'Intervals',marker:{size:4,opacity:.35}},{x:[0,max],y:[0,max],mode:'lines',name:'1:1',line:{dash:'dot',width:1}}];if(Number.isFinite(Number(m.slope))&&Number.isFinite(Number(m.intercept)))tr.push({x:[0,max],y:[Number(m.intercept),Number(m.slope)*max+Number(m.intercept)],mode:'lines',name:'OLS'});const lay=darkLayout('Available vs turbulent energy','H + LE (W m⁻²)');lay.xaxis.title='Rn − G (W m⁻²)';Plotly.newPlot('energyClosureChart',tr,lay,{responsive:true,displaylogo:false})}
