function renderPhase4(r){const u=r.ustar||{},c=r.carbon||{},f=r.footprint||{};$('#p4Ustar').textContent=u.selected_threshold!=null?fmt(u.selected_threshold,3)+' m s⁻¹':'—';$('#p4NightN').textContent=fmt(u.n_night,0);$('#p4E0').textContent=c.summary?.E0_K!=null?fmt(c.summary.E0_K,1)+' K':'—';$('#p4CarbonR2').textContent=fmt(c.summary?.night_model_r2,3);$('#p4FootN').textContent=fmt(f.summary?.valid_footprints,0);$('#p4Peak').textContent=f.summary?.median_peak_distance_m!=null?fmt(f.summary.median_peak_distance_m,0)+' m':'—';$('#phase4Status').innerHTML=`<div class="source-grid"><div class="source-card"><h4>u*</h4><div class="kv"><span>Status</span><b>${escapeHtml(u.status||'—')}</b></div><div class="kv"><span>MPT</span><b>${fmt(u.MPT?.median,3)}</b></div><div class="kv"><span>CPD</span><b>${fmt(u.CPD?.median,3)}</b></div></div><div class="source-card"><h4>Carbon</h4><div class="kv"><span>Status</span><b>${escapeHtml(c.status||'—')}</b></div><div class="kv"><span>Night N</span><b>${fmt(c.summary?.n_night_used,0)}</b></div><div class="kv"><span>RMSE</span><b>${fmt(c.summary?.night_model_rmse,2)}</b></div></div><div class="source-card"><h4>Footprint</h4><div class="kv"><span>Status</span><b>${escapeHtml(f.status||'—')}</b></div><div class="kv"><span>80% radius</span><b>${fmt(f.summary?.source_areas?.['80']?.equivalent_radius_m,0)} m</b></div></div></div>`;plotUstarP4(u);plotCarbonP4(c.daily||[]);plotFootprintP4(f);$('#aoiBody').innerHTML=(f.aoi_summary||[]).map(a=>`<tr><td>${escapeHtml(a.name)}</td><td>${a.exclude?'Yes':'No'}</td><td>${fmt(100*Number(a.mean_contribution_fraction||0),1)}%</td></tr>`).join('')||'<tr><td colspan="3">No AOI results.</td></tr>';$$('.p4export').forEach(b=>b.disabled=false);$('#exportPhase4Report').disabled=false}
function plotUstarP4(u){if(!window.Plotly)return;const a=u.overall_curve||[];if(!a.length){$('#ustarChart').innerHTML='<div class="card-body muted">u* result unavailable.</div>';return}const tr=[{x:a.map(r=>r.ustar),y:a.map(r=>r.nee),mode:'markers+lines',name:'Binned nighttime NEE'}];if(Number.isFinite(Number(u.selected_threshold)))tr.push({x:[u.selected_threshold,u.selected_threshold],y:[Math.min(...a.map(r=>r.nee)),Math.max(...a.map(r=>r.nee))],mode:'lines',name:'Selected u*',line:{dash:'dot'}});const l=darkLayout('Nighttime NEE response','NEE (µmol m⁻² s⁻¹)');l.xaxis.title='u* (m s⁻¹)';Plotly.newPlot('ustarChart',tr,l,{responsive:true,displaylogo:false})}
function plotCarbonP4(a){if(!window.Plotly)return;if(!a.length){$('#carbonChart').innerHTML='<div class="card-body muted">Carbon partitioning unavailable.</div>';return}const x=a.map(r=>String(r.date).slice(0,10));Plotly.newPlot('carbonChart',[{x,y:a.map(r=>r.NEE_gC_m2_day),name:'NEE',mode:'lines'},{x,y:a.map(r=>r.Reco_gC_m2_day),name:'Reco',mode:'lines'},{x,y:a.map(r=>r.GPP_gC_m2_day),name:'GPP',mode:'lines'}],darkLayout('Daily carbon components','g C m⁻² d⁻¹'),{responsive:true,displaylogo:false})}
function plotFootprintP4(f){if(!window.Plotly)return;if(f.status!=='ready'||!f.z?.length){$('#footprintChart').innerHTML='<div class="card-body muted">Footprint unavailable. Check required inputs.</div>';return}const l=darkLayout('Footprint climatology','North (m)');l.xaxis.title='East (m)';l.yaxis.scaleanchor='x';Plotly.newPlot('footprintChart',[{x:f.x,y:f.y,z:f.z,type:'contour',contours:{coloring:'heatmap'}}],l,{responsive:true,displaylogo:false})}
$$('.p4export').forEach(b=>b.onclick=()=>{busy(true,'Preparing carbon/footprint export',20);state.worker.postMessage({cmd:'exportPhase4',kind:b.dataset.kind})});if($('#exportPhase4Report'))$('#exportPhase4Report').onclick=()=>{busy(true,'Preparing carbon/footprint report',20);state.worker.postMessage({cmd:'exportPhase4Report'})};

/* FluxGapFill 1.0 production UI, guidance and figure export */
function cssVar(name,fallback=''){const v=getComputedStyle(document.body).getPropertyValue(name).trim();return v||fallback}
function plotTheme(){return {ink:cssVar('--ink','#edf3f7'),text:cssVar('--chart-text','#a7b6c3'),grid:cssVar('--chart-grid','rgba(255,255,255,.07)'),zero:cssVar('--line-strong','#394a5c'),axis:cssVar('--line','#293849')}}
function currentTheme(){return document.body.dataset.theme||'dark'}
function applyTheme(theme,persist=true){const allowed=['light','dark','night'];const t=allowed.includes(theme)?theme:'dark';document.body.dataset.theme=t;const sel=document.getElementById('themeSelect');if(sel&&sel.value!==t)sel.value=t;if(persist){try{localStorage.setItem('fluxgapfill-theme',t)}catch{}}refreshPlotThemes()}
function refreshPlotThemes(){if(!window.Plotly)return;const t=plotTheme();for(const id of Object.keys(FIGURE_REGISTRY)){const gd=document.getElementById(id);if(!gd||!gd.data||!gd.data.length)continue;const update={'font.color':t.text,'title.font.color':t.ink,'xaxis.gridcolor':t.grid,'xaxis.zerolinecolor':t.zero,'xaxis.linecolor':t.axis,'xaxis.tickcolor':t.axis,'yaxis.gridcolor':t.grid,'yaxis.zerolinecolor':t.zero,'yaxis.linecolor':t.axis,'yaxis.tickcolor':t.axis,'legend.font.color':t.text};if(gd.layout?.yaxis2){update['yaxis2.gridcolor']='transparent';update['yaxis2.linecolor']=t.axis;update['yaxis2.tickcolor']=t.axis;update['yaxis2.tickfont.color']=t.text;update['yaxis2.title.font.color']=t.text}try{Plotly.relayout(gd,update)}catch{}}}

const HELP_CONTENT={
 workflow:{title:'Workflow guide',lead:'FluxGapFill is modular. Complete the core import/QC/gap-filling path first; continue into energy, water, carbon or footprint modules only when those analyses are relevant to your project.',workflow:true},
 setup:{title:'Project & files',lead:'Start with already-computed fluxes or half-hourly/hourly environmental data.',need:['Primary processed file: EddyPro, Campbell TOA5, AmeriFlux/FLUXNET-style, CSV/TXT/TSV/DAT or Excel.','Optional supplemental weather/environmental file such as CIMIS.','Choose the correct time basis and timezone when the source is not self-describing.'],do:['FluxGapFill inspects the source structure locally.','The original file is never modified.','Raw 10–20 Hz sonic/IRGA processing is intentionally outside the scope.'],next:'Inspect the file, then verify every important variable and unit on Variable mapping.'},
 mapping:{title:'Variable mapping',lead:'This step prevents a wrong column or wrong unit from propagating through the analysis.',need:['Confirm timestamp convention: start, midpoint or end of averaging interval.','Confirm LE/H/NEE and environmental variables that you intend to use.','Resolve any uncertain unit rather than relying on a guess.'],do:['Known formats are auto-detected.','Generic files fall back to explicit user mapping.','Variables are normalized to the internal scientific schema.'],next:'Process the mapped project and inspect coverage on Data overview.'},
 overview:{title:'Data overview',lead:'Use this page to decide whether the standardized record is suitable for the intended analyses.',need:['Check record length and interval.','Check missingness and longest gaps for LE/H/NEE.','Look for obvious temporal discontinuities or unexpected values.'],do:['Charts are downsampled only for display. Calculations use the complete standardized record.'],next:'Proceed to Quality control when the time grid and variable coverage look correct.'},
 qc:{title:'Quality control',lead:'Use the least aggressive screen that is scientifically justified.',need:['EddyPro QC flags or other mapped QC flags when available.','Physical ranges appropriate to the variable/site.','Optional spike screening only when the data warrant it.'],do:['Original standardized values are preserved.','Rejected values are tracked in the QC audit.','The robust spike screen is optional and off by default.'],next:'Review the audit, then use Gap filling to validate reconstruction methods.'},
 modules:{title:'Module readiness',lead:'A missing optional variable should not prevent unrelated analyses.',need:['Green/Ready means the required inputs are available.','Needs data lists the missing variables or site metadata.','Skipped modules remain out of the workflow until re-enabled.'],do:['Supply missing data/metadata only for modules you actually need.'],next:'For the core gap-filling workflow, continue to Gap filling.'},
 models:{title:'Validate & fill',lead:'Validate models on contiguous hidden periods before trusting a reconstructed record.',need:['Choose LE/H/NEE targets that have enough measured data.','Balanced validation is a sensible first run.','Use Comprehensive only when you need stronger repeated-window diagnostics and have time to run it.'],do:['MDS, RF and XGBoost candidates are scored on artificial calendar gaps.','Adaptive filling can use the locally best supported method for each gap class while respecting driver availability.','Validation is retrospective reconstruction, not forecasting.'],next:'Run blocked validation, inspect RMSE/MAE/bias/R², then fill the real gaps.'},
 results:{title:'Results & provenance',lead:'A final time series is only as useful as the audit trail behind it.',need:['Compare measured and filled portions visually.','Inspect method counts and uncertainty notes.','Keep the full provenance export with any compact result you publish or archive.'],do:['Measured/QC-accepted records are not overwritten.','Filled records retain method and gap metadata.'],next:'Continue to optional domain modules or go directly to Export.'},
 energywater:{title:'Energy & water',lead:'Energy closure and water-use analyses are independent optional modules.',need:['Energy closure: H, LE, Rn and G.','ET: LE; air temperature improves latent-heat conversion.','Optional: ETo, precipitation, irrigation and SWC.','Buried heat-flux correction requires plate depth, bulk density, soil temperature and SWC.'],do:['Measured-only closure is kept separate from reconstructed-series diagnostics.','Energy-balance corrections are sensitivity products, not proof of the cause of non-closure.'],next:'Review method availability and warnings before exporting ET/water products.'},
 phase4:{title:'u*, carbon & footprint',lead:'These advanced modules require additional variables and site information; they can always be skipped.',need:['u*: NEE, u*, temperature and radiation are strongly recommended.','Carbon partitioning: NEE and temperature; u* screening is recommended.','Footprint: u*, wind direction, Monin–Obukhov length, σv, wind speed, measurement height and PBL height.','Optional AOI: GeoJSON polygons.'],do:['MPT and CPD threshold diagnostics remain separate.','Carbon uses nighttime respiration modeling.','Footprint climatology reports missing requirements instead of inventing site metadata.'],next:'Use Data & figures to download the numerical products and figures.'},
 export:{title:'Export & Figure Studio',lead:'Keep numerical results, validation diagnostics and figures together so the analysis remains reproducible.',need:['Download compact results for routine use.','Download full provenance for archiving/review.','Export validation/QC reports alongside your results.'],do:['PNG export is generated on a white print background with 600-DPI metadata.','SVG preserves editable vector graphics.','On-screen Dark/Night themes never carry into figure exports.'],next:'Choose a physical size, export format and legend position for your output.'}
};
function helpHtml(key){const h=HELP_CONTENT[key]||HELP_CONTENT.workflow;if(h.workflow){const items=[['1','Project & files','Upload processed flux/environmental data and optional supplemental weather.'],['2','Variable mapping','Confirm timestamps, variables and units.'],['3','Data overview','Check completeness and gap structure.'],['4','Quality control','Apply transparent, conservative screening.'],['5','Readiness','Supply optional module inputs or skip them.'],['6','Gap filling','Run blocked validation, compare methods, then reconstruct gaps.'],['7','Results','Inspect provenance and empirical reconstruction uncertainty.'],['8','Energy & water','Optional energy closure, ET, ETo, irrigation and SWC context.'],['9','Carbon & footprint','Optional u*, carbon partitioning and footprint climatology.'],['10','Data & figures','Download the audit trail and figures.']];return `<p class="help-lead">${h.lead}</p><div class="workflow-list">${items.map(i=>`<div class="workflow-item"><div class="workflow-number">${i[0]}</div><div><strong>${i[1]}</strong><span>${i[2]}</span></div></div>`).join('')}</div>`}return `<p class="help-lead">${h.lead}</p><div class="help-grid"><div class="help-block"><h3>What you need</h3><ul>${(h.need||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="help-block"><h3>What FluxGapFill does</h3><ul>${(h.do||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div></div><div class="help-block" style="margin-top:10px"><h3>Recommended next</h3><p>${h.next||''}</p></div>`}
function openHelp(key='workflow'){const m=document.getElementById('helpModal'),h=HELP_CONTENT[key]||HELP_CONTENT.workflow;document.getElementById('helpTitle').textContent=h.title;document.getElementById('helpBody').innerHTML=helpHtml(key);m.classList.remove('hidden');document.body.style.overflow='hidden'}
function closeHelp(){document.getElementById('helpModal')?.classList.add('hidden');document.body.style.overflow=''}

const FIGURE_REGISTRY={
 rawChart:'Mapped flux time series',qcChart:'Quality-control comparison',benchmarkChart:'Blocked-gap validation RMSE',filledChart:'Measured and gap-filled fluxes',etChart:'Daily ET from final LE',energyClosureChart:'Energy-balance closure',monthlyEbrChart:'Monthly energy-balance ratio',dailyEtP3Chart:'Daily ET and ETo',cumulativeWaterChart:'Cumulative water',waterSwcChart:'Water inputs and soil water',ustarChart:'Nighttime NEE response to u*',carbonChart:'Daily carbon components',footprintChart:'Footprint climatology'
};
const FIGURE_PRESETS={single:{label:'single',width:335,height:265},double:{label:'double',width:709,height:430},square:{label:'square',width:335,height:335}};
function renderedFigures(){return Object.entries(FIGURE_REGISTRY).filter(([id])=>{const g=document.getElementById(id);return !!(g&&g.data&&g.data.length)})}
function refreshFigureOptions(preselect=''){const sel=document.getElementById('figureSelect');if(!sel)return;const figs=renderedFigures();const old=preselect||sel.value;sel.innerHTML=figs.length?figs.map(([id,label])=>`<option value="${id}">${label}</option>`).join(''):'<option value="">Run an analysis to render figures</option>';if(figs.some(([id])=>id===old))sel.value=old;const enabled=figs.length>0;document.getElementById('exportFigureBtn').disabled=!enabled;document.getElementById('exportAllFiguresBtn').disabled=!enabled}
function decorateChartCards(){for(const [id] of Object.entries(FIGURE_REGISTRY)){const chart=document.getElementById(id),head=chart?.closest('.card')?.querySelector('.card-head');if(!chart||!head||head.querySelector(`[data-figure-jump="${id}"]`))continue;const b=document.createElement('button');b.type='button';b.className='chart-card-action';b.dataset.figureJump=id;b.textContent='Export figure';b.addEventListener('click',()=>{showView('export');refreshFigureOptions(id);setTimeout(()=>document.getElementById('figureStudio')?.scrollIntoView({behavior:'smooth',block:'center'}),120)});head.appendChild(b)}}
function sanitizeFileName(s){return String(s||'fluxgapfill').trim().replace(/[^A-Za-z0-9._-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,90)||'fluxgapfill'}
function traceCountForLegend(data){return data.filter(t=>t.showlegend!==false&&t.name).length}
function figureData(data){const palette=['#0072B2','#D55E00','#009E73','#CC79A7','#E69F00','#56B4E9','#000000','#7A7A7A'];let c=0;const groupColors={};return JSON.parse(JSON.stringify(data)).map(t=>{if(t.type==='contour'||t.type==='heatmap'){t.colorscale='Viridis';t.colorbar={...(t.colorbar||{}),tickfont:{family:'Arial, sans-serif',size:9},title:{...(t.colorbar?.title||{}),font:{family:'Arial, sans-serif',size:9}}};return t}const key=t.legendgroup;const color=t.line?.color||(key?(groupColors[key]||(groupColors[key]=palette[c++%palette.length])):palette[c++%palette.length]);if(t.line)t.line={...t.line,color,width:t.line.width===0?0:Math.max(1.1,Number(t.line.width||1.1))};else if((t.mode||'').includes('lines'))t.line={color,width:1.15};if(t.marker)t.marker={...t.marker,color,size:Math.max(3.2,Number(t.marker.size||3.2)),line:{color:'#ffffff',width:.25}};else if((t.mode||'').includes('markers'))t.marker={color,size:3.2,line:{color:'#ffffff',width:.25}};if(t.type==='bar')t.marker={...(t.marker||{}),color,line:{width:0}};if(t.fill&&t.fill!=='none'){t.fillcolor=t.fillcolor||color+'22';t.opacity=t.opacity??1}return t})}
function figureLayout(gd,preset,includeTitle,keepGrid,legendChoice){const src=gd.layout||{},n=traceCountForLegend(gd.data||[]),chars=(gd.data||[]).reduce((a,t)=>a+(t.name||'').length,0);const right=legendChoice==='right'||(legendChoice==='auto'&&(n>4||chars>72));const grid=keepGrid?'#e6e6e6':'rgba(0,0,0,0)';const axisBase={showline:true,linecolor:'#222',linewidth:1,ticks:'outside',tickcolor:'#222',tickwidth:1,ticklen:4,mirror:false,gridcolor:grid,zeroline:false,automargin:true,tickfont:{family:'Arial, sans-serif',size:9,color:'#111'},title:{font:{family:'Arial, sans-serif',size:10,color:'#111'}}};const layout={paper_bgcolor:'#ffffff',plot_bgcolor:'#ffffff',font:{family:'Arial, sans-serif',size:9.5,color:'#111'},margin:right?{l:65,r:155,t:includeTitle?48:24,b:58}:{l:65,r:24,t:includeTitle?48:24,b:n?86:58},showlegend:n>0,legend:right?{orientation:'v',x:1.02,xanchor:'left',y:1,yanchor:'top',font:{family:'Arial, sans-serif',size:8.5,color:'#111'},bgcolor:'rgba(255,255,255,0)'}:{orientation:'h',x:0,xanchor:'left',y:-.22,yanchor:'top',font:{family:'Arial, sans-serif',size:8.5,color:'#111'},bgcolor:'rgba(255,255,255,0)'},xaxis:{...axisBase,title:{...axisBase.title,text:src.xaxis?.title?.text||src.xaxis?.title||''}},yaxis:{...axisBase,title:{...axisBase.title,text:src.yaxis?.title?.text||src.yaxis?.title||''}}};if(includeTitle)layout.title={text:src.title?.text||FIGURE_REGISTRY[gd.id]||'',x:.5,xanchor:'center',font:{family:'Arial, sans-serif',size:11,color:'#111'}};if(src.barmode)layout.barmode=src.barmode;if(src.yaxis?.scaleanchor)layout.yaxis.scaleanchor=src.yaxis.scaleanchor;if(src.xaxis?.range)layout.xaxis.range=src.xaxis.range;if(src.yaxis?.range)layout.yaxis.range=src.yaxis.range;if(src.yaxis2){layout.yaxis2={...axisBase,overlaying:src.yaxis2.overlaying||'y',side:src.yaxis2.side||'right',gridcolor:'rgba(0,0,0,0)',title:{...axisBase.title,text:src.yaxis2?.title?.text||src.yaxis2?.title||''}};layout.margin.r=Math.max(layout.margin.r,right?155:78)}return layout}
function dataUrlToBlob(dataUrl){const cut=dataUrl.indexOf(','),head=cut>=0?dataUrl.slice(0,cut):'',data=cut>=0?dataUrl.slice(cut+1):dataUrl,mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';if(/;base64/.test(head)){const bin=atob(data),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return new Blob([u],{type:mime})}return new Blob([decodeURIComponent(data)],{type:mime})}
let CRC_TABLE=null;function crc32(bytes){if(!CRC_TABLE){CRC_TABLE=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):(c>>>1);CRC_TABLE[n]=c>>>0}}let c=0xffffffff;for(const b of bytes)c=CRC_TABLE[(c^b)&0xff]^(c>>>8);return (c^0xffffffff)>>>0}
async function pngWithDpi(blob,dpi=600){const u=new Uint8Array(await blob.arrayBuffer());if(u.length<33||u[0]!==137||u[1]!==80)return blob;const ppm=Math.round(dpi/0.0254),data=new Uint8Array(9),dv=new DataView(data.buffer);dv.setUint32(0,ppm);dv.setUint32(4,ppm);data[8]=1;const type=new TextEncoder().encode('pHYs'),crcInput=new Uint8Array(13);crcInput.set(type,0);crcInput.set(data,4);const chunk=new Uint8Array(21),cdv=new DataView(chunk.buffer);cdv.setUint32(0,9);chunk.set(type,4);chunk.set(data,8);cdv.setUint32(17,crc32(crcInput));let pos=8,insert=u.length;while(pos+8<u.length){const len=new DataView(u.buffer,u.byteOffset+pos,4).getUint32(0);const typ=String.fromCharCode(...u.slice(pos+4,pos+8));if(typ==='IDAT'){insert=pos;break}pos+=12+len}const out=new Uint8Array(u.length+chunk.length);out.set(u.slice(0,insert),0);out.set(chunk,insert);out.set(u.slice(insert),insert+chunk.length);return new Blob([out],{type:'image/png'})}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}
async function exportFigure(id,quiet=false){const gd=document.getElementById(id);if(!gd?.data?.length){if(!quiet)toast('Render that figure first.');return false}const presetKey=document.getElementById('figurePreset')?.value||'double',preset=FIGURE_PRESETS[presetKey]||FIGURE_PRESETS.double,format=document.getElementById('figureFormat')?.value||'png',legend=document.getElementById('figureLegend')?.value||'auto',includeTitle=!!document.getElementById('figureTitle')?.checked,keepGrid=!!document.getElementById('figureGrid')?.checked;const tmp=document.createElement('div');tmp.style.cssText='position:fixed;left:-20000px;top:0;background:#fff;';document.body.appendChild(tmp);try{const data=figureData(gd.data),layout=figureLayout(gd,preset,includeTitle,keepGrid,legend);await Plotly.newPlot(tmp,data,layout,{staticPlot:true,displayModeBar:false,responsive:false});const scale=format==='png'?6:1;const url=await Plotly.toImage(tmp,{format,width:preset.width,height:preset.height,scale});let blob=dataUrlToBlob(url);if(format==='png')blob=await pngWithDpi(blob,600);const project=sanitizeFileName(document.getElementById('projectName')?.value||document.getElementById('siteName')?.value||'FluxGapFill'),fig=sanitizeFileName(FIGURE_REGISTRY[id]||id),suffix=format==='png'?`${preset.label}_600dpi.png`:`${preset.label}_vector.svg`;downloadBlob(blob,`${project}_${fig}_${suffix}`);if(!quiet)toast(`Export figure exported: ${format==='png'?'600-DPI PNG':'SVG vector'}.`);return true}catch(err){console.error(err);if(!quiet)toast('Figure export failed: '+(err?.message||err),7000);return false}finally{try{Plotly.purge(tmp)}catch{}tmp.remove()}}

function coachState(){if(!state.primaryFile)return {view:'setup',text:'Upload a processed flux or environmental file.',button:'Go to project'};if(!state.primaryInspection)return {view:'setup',text:'Inspect the selected file and let FluxGapFill detect its structure.',button:'Inspect files'};if(!state.loaded)return {view:'mapping',text:'Verify timestamp, variable and unit mapping before processing.',button:'Review mapping'};if(!state.qcApplied)return {view:'qc',text:'Review and apply quality control before model validation.',button:'Open QC'};if(!state.benchmark)return {view:'models',text:'Run blocked validation before reconstructing real gaps.',button:'Validate models'};if(!state.filled)return {view:'models',text:'Validation is available. Review performance, then fill the real gaps.',button:'Fill gaps'};return {view:'export',text:'Results are ready. Export your data or explore the optional analyses.',button:'Open export'}}
function updateCoach(){const c=coachState(),txt=document.getElementById('coachText'),lab=document.getElementById('nextStepLabel'),btn=document.getElementById('coachAction');if(txt)txt.textContent=c.text;if(lab)lab.textContent=c.text;if(btn){btn.textContent=c.button;btn.onclick=()=>showView(c.view)}}

(function initProductionUi(){
  let initial='light';try{initial=localStorage.getItem('fluxgapfill-theme')||'light'}catch{}applyTheme(initial,false);
  document.getElementById('themeSelect')?.addEventListener('change',e=>applyTheme(e.target.value));
  document.getElementById('guideBtn')?.addEventListener('click',()=>openHelp('workflow'));
  document.getElementById('guideOpenSide')?.addEventListener('click',()=>openHelp('workflow'));
  document.getElementById('helpClose')?.addEventListener('click',closeHelp);
  document.getElementById('helpModal')?.addEventListener('click',e=>{if(e.target.id==='helpModal')closeHelp()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeHelp();if(e.key==='?'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();openHelp('workflow')}});
  document.querySelectorAll('[data-help]').forEach(b=>b.addEventListener('click',()=>openHelp(b.dataset.help)));
  document.getElementById('exportFigureBtn')?.addEventListener('click',()=>{const id=document.getElementById('figureSelect')?.value;if(id)exportFigure(id)});
  document.getElementById('exportAllFiguresBtn')?.addEventListener('click',async()=>{const figs=renderedFigures();if(!figs.length)return;toast(`Preparing ${figs.length} figures…`,2500);let count=0;for(const [id] of figs){if(await exportFigure(id,true))count++;await new Promise(r=>setTimeout(r,220))}toast(`${count} of ${figs.length} figures exported.`)});
  decorateChartCards();refreshFigureOptions();updateCoach();
})();
